input.command:
mkdir -p src/inngest "src/app/api/inngest" && 
cat > src/inngest/client.ts <<'EOF'
import { Inngest } from "inngest";

export const inngest = new Inngest({ id: "notely" });

export type UserCreatedEvent = {
  name: "user/created";
  data: { userId: string; email: string; name: string };
};
EOF
cat > src/inngest/functions.ts <<'EOF'
import { inngest } from "./client";

// Runs 10 minutes after a user is created. Inngest retries the step
// (up to `retries` times, with backoff) if it throws.
export const userReminder = inngest.createFunction(
  { id: "user-reminder", retries: 4, triggers: [{ event: "user/created" }] },
  async ({ event, step }) => {
    await step.sleep("wait-10-minutes", "10m");
    await step.run("log-reminder", async () => {
      const { userId, email, name } = event.data;
      console.log(`[reminder] Hi ${name} (${email}), user ${userId} signed up 10 minutes ago.`);
    });
  },
);

export const functions = [userReminder];
EOF
cat > src/app/api/inngest/route.ts <<'EOF'
import { serve } from "inngest/next";
import { inngest } from "@/inngest/client";
import { functions } from "@/inngest/functions";

export const { GET, POST, PUT } = serve({ client: inngest, functions });
EOF
cat > .env.example <<'EOF'
# Inngest (https://app.inngest.com). Not needed locally when using the dev server:
#   npx inngest-cli@latest dev -u http://localhost:3000/api/inngest
# and setting INNGEST_DEV=1
INNGEST_DEV=1
INNGEST_EVENT_KEY=placeholder-event-key
INNGEST_SIGNING_KEY=signkey-prod-placeholder
EOF
printf '\n!.env.example\n' >> .gitignore
cat >> src/lib/users.ts <<'EOF'

export async function createUser(input: { email: string; name: string }): Promise<User> {
  const user: User = {
    id: String(users.length + 1),
    email: input.email,
    name: input.name,
    createdAt: new Date().toISOString().slice(0, 10),
  };
  users.push(user);

  // Schedule the reminder job (runs 10 minutes later, with retries).
  // A scheduling failure must not fail user creation.
  try {
    await inngest.send({
      name: "user/created",
      data: { userId: user.id, email: user.email, name: user.name },
    });
  } catch (err) {
    console.error("Failed to schedule user reminder job", err);
  }
  return user;
}
EOF
sed -i '' '1i\
import { inngest } from "@/inngest/client";\
\
' src/lib/users.ts
npx tsc --noEmit 2>&1 | head; npx eslint src 2>&1 | tail

